// 运维费用测算：参数与基准值种子数据（本文件由抽取脚本生成，可复现）
// 数据来源：
//   A《参照国标进行测算（结合配套实际）.xlsx》—— C.1 工作量法（GB/T 28827.7-2022 附录A 因子）
//   B《设备台账__数据对齐版v2_0913.xlsx》—— 定额单价法（2008年行业维护定额）
//   C1《C1取费对照表（三张新表）.xlsx》—— C.1 设备类别 → 单位工作量
// 说明：全部数值均为「种子初值」，上线后可直接在【数据维护 → 运维参数】中增删改，
//       种子仅在表为空（或版本号变更）时灌入，不会覆盖后台已改的数据。

export const OM_SEED_VERSION = '1'

/** 人工综合成本基数：人天单价 = 月均工资 ÷ 月计薪天数 */
export interface OmWageBase {
  year: number
  region: string
  industry: string
  monthly_wage: number
  work_days: number
  is_default: boolean
  source: string
  note: string
}

/** 调整因子：engine 区分两套引擎（c1=工作量法 / quota=定额法） */
export interface OmFactor {
  group_key: string
  group_name: string
  engine: string
  name: string
  value: number
  unit: string
  calc: string
  description: string
  basis: string
  seq: number
}

/** 费率项：规费/直接非人力成本/措施费/间接费/利润/税金/备品备件/管理服务费 */
export interface OmRateItem {
  group_key: string
  group_name: string
  name: string
  rate: number
  unit: string
  base_note: string
  description: string
  seq: number
}

/** C.1 单位工作量基准：设备类别 → 人天/台·套·年 */
export interface OmC1Benchmark {
  category: string
  level: string
  unit: string
  workload: number
  source: string
  note: string
  seq: number
}

/** 定额单价库（定额法）：设备名称 → 定额值 元/月 */
export interface OmQuotaItem {
  name: string
  unit: string
  quota: number
  kind: string
  source: string
  note: string
  seq: number
}

/** 站点类型：默认数量与服务时间系数 */
export interface OmStationType {
  code: string
  name: string
  unit: string
  qty: number
  time_factor: number
  sheet_name: string
  sort: number
}

